// E1.2 (grafo §70): one e-mail when coverage goes bad, at most one every 3 hours while it stays bad,
// and one when it comes back. A refused call (error output) arrives here too and counts as unhealthy.
// Static data persists only in production executions (the active workflow), never in a manual test.
const s = $getWorkflowStaticData('global');
const body = $input.first().json;
const now = Date.now();
if (body.status === 'healthy') {
  if (!s.down) return [];
  s.down = false;
  s.lastAlert = 0;
  return [{ json: { subject: 'Cobertura do pagamento na entrega voltou ao normal', text: 'Os CEPs de São Paulo usados no alarme voltaram a responder com pagamento na entrega.\n\nVerificado em: ' + (body.checkedAt ?? new Date().toISOString()) } }];
}
s.down = true;
if (s.lastAlert && now - s.lastAlert < 3 * 3600 * 1000) return [];
s.lastAlert = now;
const checks = Array.isArray(body.checks) ? body.checks : [];
const lines = checks.length
  ? checks.map((c) => '- CEP ' + c.cep + ': ' + c.result).join('\n')
  : 'A checagem não respondeu: ' + JSON.stringify(body.error ?? body).slice(0, 500);
return [{ json: {
  subject: 'ALARME: o pagamento na entrega sumiu (ou a checagem falhou)',
  text: 'A Malu consultou CEPs de São Paulo que sempre tiveram pagamento na entrega e algum não voltou com ele.\n\n' + lines +
    '\n\ncod = ok · no_cod = a Coinzz diz que não tem · failed = a consulta falhou · not_found = CEP não achado.\n\n' +
    'Enquanto isso, clientes podem estar ouvindo que só existe o pagamento antecipado. Confira o painel da Coinzz/Logzz.\n' +
    'Este aviso se repete no máximo a cada 3 horas enquanto durar; outro e-mail avisa quando voltar.',
} }];
